    let tmp_1 = rocq_array::get::<u64>(&h, l);
    let tmp_2 = rocq_array::get::<u64>(&h, add(l, 1u64));
    if ltb(tmp_1, tmp_2) {
      std::mem::drop(h);
      add(l, 1u64)
    } else {
      std::mem::drop(h);
      l
    }
  } else {
    std::mem::drop(h);
