      match bdec(tmp_2) {
        sumbool::left => {
          let tmp_3 = rocq_array::set::<u64>(h, i, vc);
          let tmp_4 = rocq_array::set::<u64>(tmp_3, c, vi);
          sift_down(tmp_4, s, c, ())
        },
        sumbool::right => {
          h
