  let tmp_1 = (tmp, 0u64);
  let tmp_2 = rocq_array::make::<u64>(n, 0u64);
  let st0 = step((tmp_1, tmp_2), y, p);
  let tmp_3 = fill_1(ys, ps, m, 0u64, st0);
  match tmp_3 {
    (v67, v69) => {
